      .on('click', function () {
        showPopup('The unit circle',
          'This circle has radius 1. Turning through an angle x lands you on the point (cos x, sin x). Because the radius is 1, the height of that point is exactly sin x — no extra scaling needed.');
      });

    // ---- right panel: axes ----
    var xL = gx(-L.leftSpan), xR = L.areaR;
    gAxes.line(xL, cy, xR, cy).stroke({ color: BLACK, width: axis });
    arrowAt(gAxes, xR + aw * 0.85, cy, 0, aw, BLACK);
    arrowAt(gAxes, xL - aw * 0.85, cy, P, aw, BLACK);
    gAxes.line(ox, cy - 1.42 * R, ox, cy + 1.30 * R).stroke({ color: BLACK, width: axis });
    arrowAt(gAxes, ox, cy - 1.42 * R - aw * 0.85, -P / 2, aw, BLACK);

    var tk = Math.max(3, R * 0.055);
    [1, -1].forEach(function (v) {
      gAxes.line(ox - tk, gy(v), ox + tk, gy(v)).stroke({ color: BLACK, width: axis });
    });
    var ffs = fs * 0.92;
    var showMinor = (kx * 0.2618) >= ffs * 1.0;
    SPECIALS.forEach(function (sp) {
      gAxes.line(gx(sp.t), cy - tk, gx(sp.t), cy + tk).stroke({ color: BLACK, width: axis * 0.85 });
    });

    // ---- special-angle markers ----
    if (state.specials) {
      SPECIALS.forEach(function (sp) {
        var s = Math.sin(sp.t), y = gy(s);
        var cpx = cx + R * Math.cos(sp.t), X = gx(sp.t);
        gSpec.line(cpx, y, X, y).stroke({ color: TEAL, width: Math.max(1.1, R * 0.017), dasharray: dash(0.075, 0.05) });
        gSpec.line(X, y, X, cy).stroke({ color: ORANGE, width: Math.max(1.2, R * 0.019), dasharray: dash(0.06, 0.04) });
        gSpec.circle(Math.max(3.5, R * 0.05)).center(X, y).fill(ORANGE);
        hit(gSpec, X, y, X, cy, 'sin(' + sp.lab + ') = ' + sp.val,
          'sin(' + sp.lab + ') = ' + sp.val,
          'The orange segment marks the angle ' + sp.lab + ' on the x-axis; its length is the height of the curve there. The teal line carries that same height back to the unit circle, where it is the vertical coordinate of the point at ' + sp.lab + '.');
        hit(gSpec, cpx, y, X, y, 'Same height on circle and graph: ' + sp.val,
          'Equal heights',
          'Both ends of this dashed line sit at the same height. On the left it is the y-coordinate of the circle point; on the right it is the value of sin(' + sp.lab + ').');
      });
    }

    // ---- the sine curve ----
    var pts = sinePts(-L.leftSpan + 0.05, L.curveEnd, 300);
    gCurve.polyline(ptsStr(pts)).fill('none')
      .stroke({ color: NAVY, width: Math.max(2, R * 0.038), linecap: 'round', linejoin: 'round' });
    var a0 = pts[0], a1 = pts[2];
    arrowAt(gCurve, a0[0], a0[1], Math.atan2(a0[1] - a1[1], a0[0] - a1[0]), aw * 1.05, NAVY);
    var b0 = pts[pts.length - 1], b1 = pts[pts.length - 3];
    arrowAt(gCurve, b0[0], b0[1], Math.atan2(b0[1] - b1[1], b0[0] - b1[0]), aw * 1.05, NAVY);

    var step = Math.max(10, Math.floor(pts.length / 16));
    for (var i = 0; i + step < pts.length; i += step) {
      hit(gCurve, pts[i][0], pts[i][1], pts[i + step][0], pts[i + step][1],
        'y = sin(x): the height of the circle point at angle x',
        'The sine curve',
        'Each point (x, sin x) records the height of the unit-circle point after turning through the angle x. Follow any teal dashed line: the circle height and the graph height are the same number.');
    }

    // ---- extra ticks once the curve runs further ----
    [[P, 'π'], [3 * P / 2, '3π/2'], [2 * P, '2π']].forEach(function (q) {
      if (q[0] > L.curveEnd + 0.05) return;
      gAxes.line(gx(q[0]), cy - tk * 0.85, gx(q[0]), cy + tk * 0.85).stroke({ color: '#8a8a8a', width: axis * 0.8 });
      label(gLabels, q[1], gx(q[0]), cy + fs * 2.0, { size: ffs * 0.95, color: '#777' });
    });

    // ---- labels (drawn last, on top) ----
    label(gLabels, 'y', ox - fs * 0.95, cy - 1.42 * R - aw * 1.35, { size: fs * 1.3, italic: true, weight: 'bold' });
    label(gLabels, 'x', L.areaR + aw * 0.5, cy - fs * 1.0, { size: fs * 1.3, italic: true, weight: 'bold', anchor: 'end' });
    label(gLabels, '1', ox - fs * 0.75, gy(1) + fs * 0.35, { size: fs, anchor: 'end' });
    label(gLabels, '-1', ox - fs * 0.75, gy(-1) + fs * 0.35, { size: fs, anchor: 'end' });
    label(gLabels, '0', ox - fs * 0.45, cy + fs * 1.5, { size: fs, anchor: 'end' });

    SPECIALS.forEach(function (sp) {
      if (!showMinor && sp.t < 1.5) return;
      frac(gLabels, sp.num, sp.den, gx(sp.t), cy + fs * 1.55, BLACK, ffs);
    });

    var tx = Math.min(gx(Math.min(2.0, L.curveEnd - 0.4)), L.areaR - fs * 2.2);
    var cl = label(gLabels, 'y = sin(x)', tx, cy - 1.30 * R, { size: fs * 1.15, italic: true, color: BLUE });
    cl.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('The sine graph: angle on the x-axis, height on the y-axis', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('y = sin(x)',
          'The horizontal axis is the angle x (in radians) and the vertical axis is the height of the circle point. The curve is simply a running record of that height as the radius turns.');
      });
  }

  // ================= ACTIVE (moving) ELEMENTS =================
  function drawActive() {
    gAct.clear();
    var R = L.R, cx = L.cx, cy = L.cy;
    var a = state.angle, s = Math.sin(a), c = Math.cos(a);
    var px = cx + R * c, py = cy - R * s;
    var mx = gx(a), my = gy(s);
    var wThick = Math.max(2, R * 0.035);

    if (state.sweeping && a > 0.01) {
      gAct.polyline(ptsStr(sinePts(0, a, 160))).fill('none')
        .stroke({ color: BLUE, width: wThick * 1.8, linecap: 'round', opacity: 0.5 });
    }

    if (a > 0.03) {
      var ar = R * 0.30;
      var d = 'M ' + (cx + ar) + ' ' + cy + ' A ' + ar + ' ' + ar + ' 0 ' + (a > P ? 1 : 0) +
        ' 0 ' + (cx + ar * Math.cos(a)).toFixed(2) + ' ' + (cy - ar * Math.sin(a)).toFixed(2);
      gAct.path(d).fill('none').stroke({ color: BLUE, width: Math.max(1.1, R * 0.018) });
    }

    gAct.line(cx, cy, px, py).stroke({ color: NAVY, width: wThick, linecap: 'round' });
    gAct.line(px, py, px, cy).stroke({ color: NAVY, width: wThick * 0.8, linecap: 'round' });
    gAct.line(px, py, mx, my).stroke({ color: TEAL, width: Math.max(1.5, R * 0.024), dasharray: dash(0.09, 0.05) });
    gAct.line(mx, my, mx, cy).stroke({ color: ORANGE, width: Math.max(1.3, R * 0.021), dasharray: dash(0.055, 0.04) });
    gAct.circle(Math.max(4, R * 0.062)).center(mx, cy).fill(ORANGE);
    gAct.circle(Math.max(6, R * 0.11)).center(px, py).fill(NAVY).stroke({ color: '#fff', width: Math.max(1.2, R * 0.019) });
    gAct.circle(Math.max(6.5, R * 0.12)).center(mx, my).fill(NAVY).stroke({ color: '#fff', width: Math.max(1.2, R * 0.02) });

    var fr = niceFrac(a);
    var tipA = 'Point on the circle: (cos x, sin x) = (' + c.toFixed(3) + ', ' + s.toFixed(3) + ')';
    hit(gAct, cx, cy, px, py, 'Radius at angle x' + (fr ? ' = ' + fr : '') + ' (length 1)',
      'The rotating radius',
      'The radius always has length 1. After turning through angle x it ends at the point (cos x, sin x), so the point\'s height above the horizontal axis is sin x.');
    hit(gAct, px, py, px, cy, 'Height of the point = sin x = ' + s.toFixed(3),
      'Height = sine', tipA + '. The vertical blue segment is that height, and it is exactly the y-value plotted on the graph.');
    hit(gAct, px, py, mx, my, 'Same height, two pictures: sin x = ' + s.toFixed(3),
      'One fact, told twice',
      'This dashed line is horizontal, so both ends are at the same height. The left end is the circle point; the right end is the point (x, sin x) on the graph.');
  }

  // ================= READOUT =================
  function drawReadout() {
    gRead.clear();
    var fs = L.fs, a = state.angle, s = Math.sin(a), fr = niceFrac(a);
    var x = L.pad + 2, y0 = L.pad + fs * 1.05;
    label(gRead, 'x = ' + (fr ? fr + ' ≈ ' : '') + a.toFixed(2) + ' rad', x, y0,
      { size: fs * 0.95, family: SANS, anchor: 'start', color: '#444' });
    label(gRead, 'sin x = height = ' + s.toFixed(3), x, y0 + fs * 1.35,
      { size: fs * 1.0, family: SANS, anchor: 'start', color: NAVY, weight: 'bold' });
  }

  // ================= RENDER =================
  function render() {
    var nl = computeLayout();
    var key = [nl.w, nl.h, nl.R.toFixed(2), nl.kx.toFixed(2), nl.ox.toFixed(2), nl.cy.toFixed(2),
      nl.curveEnd.toFixed(2), state.specials ? 1 : 0].join('|');
    var resized = (!L || L.w !== nl.w || L.h !== nl.h);
    L = nl;
    if (resized) draw.viewbox(0, 0, L.w, L.h);
    if (key !== lastKey) { lastKey = key; drawStatic(); }
    drawActive();
    drawReadout();
  }

  document.addEventListener('fig-resize', function () { render(); });

  // ================= CONTROLS =================
  function setSlider(v) {
    var inp = document.getElementById('angleInput');
    if (inp) inp.value = v;
    var out = document.getElementById('angleVal');
    if (out) out.value = (+v).toFixed(2);
  }
  function setAngle(v) {
    state.angle = Math.max(0, Math.min(6.283, v));
    setSlider(state.angle);
    render();
  }

  window.update_angle = function (v) {
    if (state.sweeping) stopSweep();
    state.angle = v;
    render();
  };
  window.toggle_specialAngles = function (on) {
    state.specials = !!on;
    render();
  };

  var raf = 0, last = 0, sweepT = 0;
  function startSweep() {
    if (state.sweeping) return;
    state.sweeping = true;
    var b = document.getElementById('sweepBtn');
    if (b) { b.textContent = '⏸ Pause sweep'; b.classList.add('active'); }
    sweepT = 0;
    last = performance.now();
    raf = requestAnimationFrame(tick);
  }
  function stopSweep() {
    if (!state.sweeping) return;
    state.sweeping = false;
    cancelAnimationFrame(raf);
    var b = document.getElementById('sweepBtn');
    if (b) { b.textContent = '▶ Sweep the radius 0 → π/2'; b.classList.remove('active'); }
    render();
  }
  function tick(ts) {
    if (!state.sweeping) return;
    var dt = Math.min(0.05, (ts - last) / 1000);
    last = ts;
    sweepT += dt * 0.55;
    if (sweepT > P / 2 + 0.7) sweepT = 0;
    setAngle(Math.min(sweepT, P / 2));
    raf = requestAnimationFrame(tick);
  }
  window.trigger_quarterSweep = function () {
    if (state.sweeping) stopSweep(); else startSweep();
  };

  // ================= DEMO STEPS =================
  var STEPS = [
    {
      title: 'Two pictures, one function',
      narration: 'On the left a point rides the unit circle; on the right the same information is plotted against the angle. The dashed teal line connects them at the same height.',
      state: { angle: 0.5236, specials: true, sweep: false }
    },
    {
      title: 'Read the special angles',
      narration: 'Drag to π/6, π/4, π/3: each orange drop line marks the angle on the x-axis while the teal line marks the matching height on the circle — 1/2, √2/2, √3/2.',
      state: { angle: 1.0472, specials: true, sweep: false }
    },
    {
      title: 'The quarter-turn peak',
      narration: 'At x = π/2 the radius points straight up, the circle point\'s height is the full radius 1, and the graph reaches its maximum.',
      state: { angle: 1.5708, specials: true, sweep: false }
    },
    {
      title: 'Watch the record being written',
      narration: 'The sweep is playing: as the radius rotates from 0 to π/2, the curve is traced from the origin to its peak — the graph is the height, plotted moment by moment.',
      state: { angle: 1.5708, specials: false, sweep: true }
    },
    {
      title: 'Past the peak, and below the axis',
      narration: 'Keep dragging past π/2: the height shrinks back to 0 at π, then goes negative in the third and fourth quadrants — quadrant position explains the sign of sine.',
      state: { angle: 4.1888, specials: false, sweep: false }
    }
  ];
  var stepIdx = 0;

  function applyStep(i) {
    stepIdx = (i + STEPS.length) % STEPS.length;
    var st = STEPS[stepIdx];
    stopSweep();
    var cb = document.getElementById('specialAnglesInput');
    if (cb) cb.checked = st.state.specials;
    state.specials = st.state.specials;
    setAngle(st.state.angle);
    var t = document.getElementById('stepTitle');
    if (t) t.textContent = (stepIdx + 1) + '. ' + st.title;
    var n = document.getElementById('demoNarration');
    if (n) n.textContent = st.narration;
    var l = document.getElementById('stepLabel');
    if (l) l.textContent = 'Step ' + (stepIdx + 1) + ' / ' + STEPS.length;
    if (st.state.sweep) startSweep();
  }
  window.nextStep = function () { applyStep(stepIdx + 1); };
  window.prevStep = function () { applyStep(stepIdx - 1); };

  // ================= INIT =================
  applyStep(0);
  setTimeout(render, 0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
